## Why This Is Asked
Tests ability to design a CGO boundary with explicit memory management, buffer sizing strategy, and error handling for a common pre-allocated-buffer pattern.

## Key Concepts
- CGO memory ownership and memory safety at the boundary
- Pre-allocated buffers with retry logic
- Converting C strings to Go safely

## Code Example
```c
// header
int ints_to_json(const int32_t* data, size_t n, char* out, size_t out_len);
```

```c
// minimal impl: writes [a,b,...] or -1 if too small
#include <stdint.h>
#include <stdio.h>

int ints_to_json(const int32_t* data, size_t n, char* out, size_t out_len) {
    int needed = snprintf(NULL, 0, "[%d", data[0]);
    for (size_t i = 1; i < n; i++) {
        needed += snprintf(NULL, 0, ",%d", data[i]);
    }
    needed += 1; // closing bracket
    if ((size_t)needed > out_len) return -1;
    char *ptr = out;
    ptr += sprintf(ptr, "[%d", data[0]);
    for (size_t i = 1; i < n; i++) {
        ptr += sprintf(ptr, ",%d", data[i]);
    }
    *ptr = ']';
    return 0;
}
```

```go
//go:build cgo
package main

/*
#include <stdint.h>
#include <stdlib.h>

int ints_to_json(const int32_t* data, size_t n, char* out, size_t out_len);
*/
import "C"
import "unsafe"

func IntsToJSON(nums []int32) (string, error) {
    n := len(nums)
    sizes := []C.size_t{1024, 4096}

    for _, size := range sizes {
        buf := C.malloc(size)
        defer C.free(unsafe.Pointer(buf))

        ret := C.ints_to_json((*C.int32_t)(unsafe.Pointer(&nums[0])), C.size_t(n), (*C.char)(buf), size)
        if ret == 0 {
            return C.GoString((*C.char)(buf)), nil
        }
    }
    return "", fmt.Errorf("buffer too small even at 4096 bytes")
}
```

